@cocotb.test(timeout_time=100, timeout_unit="us")  # a broken DUT must fail, not hang
async def tc_smoke(dut):
    """Hand-written values through cocotbext-axi: ID and VERSION read their constants, SCRATCH reads
    back what was written, an unmapped address and a write to a read-only register answer SLVERR
    without a side effect."""
    await start(dut)
    axil = AxiLiteMaster(AxiLiteBus.from_prefix(dut, "s_axil"), dut.clk, dut.rst)

    async def read32(addr):
        r = await axil.read(addr, 4)
        return int.from_bytes(r.data, "little"), r.resp

    async def write32(addr, value):
        return (await axil.write(addr, value.to_bytes(4, "little"))).resp

    assert await read32(ID) == (0x48465431, AxiResp.OKAY)
    assert await read32(VERSION) == (0x0005_0002, AxiResp.OKAY)
    assert await read32(SCRATCH) == (0, AxiResp.OKAY), "SCRATCH reset value"
    for _ in range(8):
        value = random.getrandbits(32)
        assert await write32(SCRATCH, value) == AxiResp.OKAY
        assert await read32(SCRATCH) == (value, AxiResp.OKAY)
    assert (await read32(UNMAPPED))[1] == AxiResp.SLVERR
    assert await write32(UNMAPPED, 0x1234_5678) == AxiResp.SLVERR
    assert await write32(ID, 0) == AxiResp.SLVERR
    assert await read32(ID) == (0x48465431, AxiResp.OKAY), "a rejected write changed ID"
    assert await read32(SCRATCH) == (value, AxiResp.OKAY), "a rejected write changed SCRATCH"


@cocotb.test(timeout_time=200, timeout_unit="us")  # a broken DUT must fail, not hang
async def tc_reset_values(dut):
    """After reset every readable register reads its reset value (hardware-driven fields: the
    driven input), every hwif output holds its reset value and no pulse fired."""
    csr, drv = await start_driver(dut)
    await check_all_reads(csr, drv)
    await csr.check_outputs()


@cocotb.test(timeout_time=2, timeout_unit="ms")  # a broken DUT must fail, not hang
async def tc_rw_all(dut):
    """Random full-word writes to every writable register (several rounds), then every register is
    read; the model also answers the RO writes and WO reads (SLVERR)."""
    csr, drv = await start_driver(dut)
    rng = random.Random(random.getrandbits(32))
    for _ in range(4):
        for a in writable(csr):
            data = rng.getrandbits(32)
            assert await drv.write(a, data) == csr.expect_write(a, data, 0xF), f"write {a:#06x}"
        await check_all_reads(csr, drv)
        for r in csr.model.regs:
            if not r.writable:
                assert await drv.write(r.addr, rng.getrandbits(32)) == csr.expect_write(r.addr, 0, 0xF) == SLVERR
            if not r.readable:
                assert await drv.read(r.addr) == (0, SLVERR)
        await csr.check_outputs()


@cocotb.test(timeout_time=2, timeout_unit="ms")  # a broken DUT must fail, not hang
async def tc_partial_wstrb(dut):
    """Every WSTRB value (0x0..0xF) on every writable register: only the enabled bytes change, a
    singlepulse field fires only when its byte is enabled and set."""
    csr, drv = await start_driver(dut)
    rng = random.Random(random.getrandbits(32))
    for strb in range(16):
        for a in writable(csr):
            data = rng.getrandbits(32) | 1  # bit 0 set: a pulse field fires if byte 0 is enabled
            assert await drv.write(a, data, strb) == csr.expect_write(a, data, strb)
        await check_all_reads(csr, drv)
    await csr.check_outputs()


@cocotb.test(timeout_time=2, timeout_unit="ms")  # a broken DUT must fail, not hang
async def tc_unmapped_and_illegal(dut):
    """Unmapped addresses (block gaps, reserved blocks, the rest of the window), writes to read-only
    and reads from write-only registers: SLVERR, rdata 0, and no register, output or pulse
    changes. Unaligned addresses select the register of their word."""
    csr, drv = await start_driver(dut)
    rng = random.Random(random.getrandbits(32))
    for a in writable(csr):  # non-reset contents, so a stray write would show
        data = rng.getrandbits(32) & ~1
        csr.expect_write(a, data, 0xF)
        await drv.write(a, data)
    for a in unmapped(csr, rng, 200):
        assert await drv.read(a) == (0, SLVERR), f"read {a:#06x}"
        assert await drv.write(a, rng.getrandbits(32) | 1) == SLVERR, f"write {a:#06x}"
    for r in csr.model.regs:
        if not r.writable:
            assert await drv.write(r.addr, rng.getrandbits(32) | 1) == SLVERR, f"write RO {r.path}"
        if not r.readable:
            assert await drv.read(r.addr) == (0, SLVERR), f"read WO {r.path}"
    for a in rng.sample(readable(csr), 8):
        off = rng.randrange(1, 4)
        assert await drv.read(a + off) == csr.model.read(a), f"unaligned read {a + off:#06x}"
    await check_all_reads(csr, drv)
    await csr.check_outputs()


@cocotb.test(timeout_time=1, timeout_unit="ms")  # a broken DUT must fail, not hang
async def tc_hw_inputs(dut):
    """Hardware-driven fields read the current input (no storage), new values on every read, and
    STATS_SEQ counts incr pulses (back to back and with gaps)."""
    csr, drv = await start_driver(dut)
    rng = random.Random(random.getrandbits(32))
    for _ in range(5):
        csr.drive_hw_inputs(rng)
        await RisingEdge(dut.clk)
        await check_all_reads(csr, drv)
    incr = node(dut.hwif_in, "STATS.STATS_SEQ.seq.incr")
    for n in (1, 3, 2):
        for _ in range(n):
            incr.value = 1
            await RisingEdge(dut.clk)
        incr.value = 0
        await RisingEdge(dut.clk)
        csr.seq_incr += n
        csr.model.hw["STATS.STATS_SEQ.seq"] = csr.seq_incr
        assert await drv.read(STATS_SEQ) == (csr.seq_incr, OKAY)


@cocotb.test(timeout_time=2, timeout_unit="ms")  # a broken DUT must fail, not hang
async def tc_k6_w_before_aw_data_changes(dut):
    """K6: W arrives before AW (and with it, and after it), and WDATA/WSTRB/AWADDR turn to garbage
    right after their handshakes. The block must store what was accepted."""
    csr, drv = await start_driver(dut)
    rng = random.Random(random.getrandbits(32))
    targets = [r.addr for r in csr.model.regs if r.writable and r.readable]
    for i in range(120):
        a = rng.choice(targets)
        data, strb = rng.getrandbits(32), rng.choice([0xF, rng.getrandbits(4)])
        aw_delay, w_delay = [(rng.randint(1, 6), 0), (0, 0), (0, rng.randint(1, 6))][i % 3]
        want = csr.expect_write(a, data, strb)
        assert await drv.write(a, data, strb, aw_delay=aw_delay, w_delay=w_delay) == want
        assert await drv.read(a) == csr.model.read(a), f"write {i} to {a:#06x}"
    assert set(drv.write_orders()) == {"aw_first", "w_first", "same"}
    await csr.check_outputs()


@cocotb.test(timeout_time=5, timeout_unit="ms")  # a broken DUT must fail, not hang
async def tc_k7_writes_under_b_backpressure(dut):
    """K7: many writes in flight while BREADY is mostly low. Every accepted write gets exactly one
    B, in order, with its own BRESP (legal and illegal writes mixed); then the contents match."""
    csr, drv = await start_driver(dut)
    rng = random.Random(random.getrandbits(32))
    drv.b_ready_p = 0.1
    addrs = writable(csr) + [r.addr for r in csr.model.regs if not r.writable] + unmapped(csr, rng, 10)
    pending = []
    for _ in range(300):
        a, data, strb = rng.choice(addrs), rng.getrandbits(32), rng.getrandbits(4)
        pending.append((drv.write_nowait(a, data, strb), csr.expect_write(a, data, strb), a))
    for p, want, a in pending:
        assert (await p.wait())[1] == want, f"BRESP of write to {a:#06x}"
    assert drv.stalled["b"] > 100 and drv.max_outstanding["w"] >= 2
    drv.b_ready_p = 1.0
    await check_all_reads(csr, drv)
    await csr.check_outputs()


@cocotb.test(timeout_time=5, timeout_unit="ms")  # a broken DUT must fail, not hang
async def tc_k8_reads_under_r_backpressure(dut):
    """K8: many reads in flight while RREADY is mostly low, ARADDR garbage after each handshake.
    Every AR gets exactly one R, in order, with the data of its own address."""
    csr, drv = await start_driver(dut)
    rng = random.Random(random.getrandbits(32))
    for a in writable(csr):
        data = rng.getrandbits(32) & ~1
        csr.expect_write(a, data, 0xF)
        await drv.write(a, data)
    drv.r_ready_p = 0.1
    addrs = [r.addr for r in csr.model.regs] + unmapped(csr, rng, 10)
    pending = []
    for _ in range(300):
        a = rng.choice(addrs)
        pending.append((drv.read_nowait(a, delay=rng.randint(0, 2)), a))
    for p, a in pending:
        assert await p.wait() == csr.model.read(a), f"read {a:#06x}"
    assert drv.stalled["r"] > 100 and drv.max_outstanding["r"] >= 2
    await csr.check_outputs()


@cocotb.test(timeout_time=2, timeout_unit="ms")  # a broken DUT must fail, not hang
async def tc_back_to_back(dut):
    """cocotbext-axi with concurrent writes and reads on disjoint registers, no backpressure."""
    csr = await start(dut)
    axil = AxiLiteMaster(AxiLiteBus.from_prefix(dut, "s_axil"), dut.clk, dut.rst)
    rng = random.Random(random.getrandbits(32))
    filters = [r.addr for r in csr.model.regs if r.path.startswith("NET.FILTER")]
    consts = [ID, VERSION]

    async def writer():
        for _ in range(100):
            a, data = rng.choice(filters), rng.getrandbits(32)
            want = csr.expect_write(a, data, 0xF)
            assert (await axil.write(a, data.to_bytes(4, "little"))).resp == want

    async def reader():
        for _ in range(100):
            a = rng.choice(consts)
            r = await axil.read(a, 4)
            assert (int.from_bytes(r.data, "little"), int(r.resp)) == csr.model.read(a)

    tasks = [cocotb.start_soon(writer()), cocotb.start_soon(reader())]
    for t in tasks:
        await t
    for _ in range(4):
        await RisingEdge(dut.clk)
    for a in readable(csr):
        r = await axil.read(a, 4)
        assert (int.from_bytes(r.data, "little"), int(r.resp)) == csr.model.read(a), f"read {a:#06x}"
    await csr.check_outputs()


@cocotb.test(timeout_time=5, timeout_unit="ms")  # a broken DUT must fail, not hang
async def tc_symbol_mem(dut):
    """SYMBOL through the external interface: every WSTRB on the first, the last and random words,
    read back; responder delays from 1 to 40 cycles; register accesses issued behind a SYMBOL
    access wait for its ack (one external access in flight) and stay correct; one request per
    access; unaligned addresses select their word."""
    csr, drv = await start_driver(dut)
    rng = random.Random(random.getrandbits(32))
    words = symbol_addrs(rng, 12)
    accesses = 0
    for strb in range(16):
        for a in words:
            data = rng.getrandbits(32)
            assert await drv.write(a, data, strb) == csr.expect_write(a, data, strb) == OKAY
            accesses += 1
        for a in words:
            assert await drv.read(a) == csr.model.read(a), f"read {a:#06x}"
            accesses += 1
    for a in rng.sample(words, 4):
        assert await drv.read(a + rng.randrange(1, 4)) == csr.model.read(a), "unaligned read"
        accesses += 1
    csr.mem_delay = (30, 40)
    for _ in range(20):
        a, data = rng.choice(words), rng.getrandbits(32)
        pend = [drv.write_nowait(a, data), drv.read_nowait(SCRATCH), drv.read_nowait(a)]
        want = [csr.expect_write(a, data, 0xF), csr.model.read(SCRATCH), csr.model.read(a)]
        assert (await pend[0].wait())[1] == want[0]
        assert await pend[1].wait() == want[1] and await pend[2].wait() == want[2]
        accesses += 2
    assert csr.mem_requests == accesses, f"{csr.mem_requests} SYMBOL requests for {accesses} accesses"
    await check_all_reads(csr, drv)
    await csr.check_outputs()


@cocotb.test(timeout_time=5, timeout_unit="ms")  # a broken DUT must fail, not hang
async def tc_reset_mid_traffic(dut):
    """AxilDriver.reset() (audit/12 S7): writes and reads (SCRATCH, NET filters, SYMBOL with a slow
    responder) in flight under B/R backpressure when the block is reset, 10 times at random points.
    The driver drops the requests left without a response and fails if one still gets an answer;
    after each reset, traffic on the same registers is exact against the model from reset values,
    so the driver's bookkeeping recovered too."""
    csr, drv = await start_driver(dut)
    rng = random.Random(random.getrandbits(32))
    regs = [SCRATCH] + [r.addr for r in csr.model.regs if r.path.startswith("NET.FILTER")]  # no pulse fields
    dropped = answered = 0
    for _ in range(10):
        csr.mem_delay = (1, 20)
        drv.b_ready_p, drv.r_ready_p = rng.choice([1.0, 0.3]), rng.choice([1.0, 0.3])
        pend = []
        for _ in range(rng.randint(2, 8)):
            a = rng.choice(regs + symbol_addrs(rng, 3))
            pend.append(drv.write_nowait(a, rng.getrandbits(32)) if rng.random() < 0.5 else drv.read_nowait(a))
        for _ in range(rng.randint(0, 20)):
            await RisingEdge(dut.clk)
        dut.rst.value = 1
        drv.reset(dut.rst)
        for _ in range(3):
            await RisingEdge(dut.clk)
        dut.rst.value = 0
        await RisingEdge(dut.clk)
        csr.model.reset()
        csr.ram.clear()  # the bitmap behind hft_csr_wrap is cleared after a reset too
        dropped += sum(q.dropped for q in pend)
        answered += sum(q.done.is_set() for q in pend)
        assert all(q.dropped != q.done.is_set() for q in pend), "a request both answered and dropped, or neither"
        drv.b_ready_p = drv.r_ready_p = 1.0
        csr.mem_delay = (1, 8)
        for a in regs + symbol_addrs(rng, 4):
            data = rng.getrandbits(32)
            assert await drv.write(a, data) == csr.expect_write(a, data, 0xF), f"write {a:#06x} after a reset"
            assert await drv.read(a) == csr.model.read(a), f"read {a:#06x} after a reset"
    assert dropped > 0 and answered > 0, f"{dropped} dropped, {answered} answered: both kinds of reset point"


def axil_bins(csr: Csr) -> list[str]:
    bins = ["order_aw_first", "order_w_first", "order_same", "b_stalled", "r_stalled"]
    bins += ["outstanding_w2", "outstanding_r2"]
    bins += [f"read_{r.path}" for r in csr.model.regs if r.readable]
    bins += [f"write_{r.path}" for r in csr.model.regs if r.writable]
    bins += [f"wstrb_byte{i}" for i in range(4)] + ["wstrb_none", "wstrb_full", "wstrb_mixed"]
    bins += ["err_read_unmapped", "err_write_unmapped", "err_write_ro", "err_read_wo"]
    bins += ["read_SYMBOL", "write_SYMBOL"]
    return bins


@cocotb.test(timeout_time=20, timeout_unit="ms")  # a broken DUT must fail, not hang
async def tc_axil_random(dut):
    """Random traffic with the coverage gate of audit/10 §2.12 (bus bins; the CDC bins are in the
    integration test): writes and reads in flight together, each phase on disjoint register sets
    (the order between the write and read channels is not defined), random delays, WSTRB and
    BREADY/RREADY; every response checked against the model in order."""
    csr, drv = await start_driver(dut)
    rng = random.Random(random.getrandbits(32))
    cov = Coverage("hft_csr.tc_axil_random", axil_bins(csr))
    by_addr = csr.model.by_addr
    regs = [r.addr for r in csr.model.regs]
    # Phases in pairs: a random split of the map into two halves, then the same halves swapped, so
    # every register is written and read (the register bins do not depend on the seed). Each phase
    # covers its sets round-robin and adds random extra accesses.
    phases = []
    for _ in range(12):
        rng.shuffle(regs)
        a, b = regs[: len(regs) // 2], regs[len(regs) // 2 :]
        phases += [(a, b), (b, a)]
    sym_w, sym_r = symbol_addrs(rng, 8), symbol_addrs(rng, 8)
    sym_r = [a for a in sym_r if a not in sym_w] or [SYMBOL.addr + 8]
    for wbase, rbase in phases:
        wset = wbase + unmapped(csr, rng, 2) + rng.sample(sym_w, 2)
        rset = rbase + unmapped(csr, rng, 2) + rng.sample(sym_r, 2)
        drv.b_ready_p, drv.r_ready_p = rng.choice([1.0, 0.5, 0.15]), rng.choice([1.0, 0.5, 0.15])
        ops = [("w", x) for x in wset] + [("r", x) for x in rset]
        ops += [("w", rng.choice(wset)) for _ in range(5)] + [("r", rng.choice(rset)) for _ in range(5)]
        rng.shuffle(ops)
        writes, reads = [], []
        for kind, a in ops:
            if kind == "w":
                data = rng.getrandbits(32)
                strb = rng.choice([0xF, 0x0, 1 << rng.randrange(4), rng.getrandbits(4)])
                aw_d, w_d = rng.choice([(0, 0), (rng.randint(1, 4), 0), (0, rng.randint(1, 4))])
                writes.append((drv.write_nowait(a, data, strb, aw_d, w_d), csr.expect_write(a, data, strb), a, strb))
            else:
                reads.append((drv.read_nowait(a, rng.randint(0, 2)), csr.model.read(a), a))
        for p, want, a, strb in writes:
            assert (await p.wait())[1] == want, f"BRESP of write to {a:#06x}"
            reg = by_addr.get(a)
            if SYMBOL.word(a) is not None:
                cov.hit("write_SYMBOL")
            elif reg is None:
                cov.hit("err_write_unmapped")
            elif not reg.writable:
                cov.hit("err_write_ro")
            else:
                cov.hit(f"write_{reg.path}")
                if strb == 0:
                    cov.hit("wstrb_none")
                elif strb == 0xF:
                    cov.hit("wstrb_full")
                elif strb in (1, 2, 4, 8):
                    cov.hit(f"wstrb_byte{strb.bit_length() - 1}")
                else:
                    cov.hit("wstrb_mixed")
        for p, want, a in reads:
            assert await p.wait() == want, f"read {a:#06x}"
            reg = by_addr.get(a)
            if SYMBOL.word(a) is not None:
                cov.hit("read_SYMBOL")
                continue
            cov.hit("err_read_unmapped" if reg is None else "err_read_wo" if not reg.readable else f"read_{reg.path}")
    for order in drv.write_orders():
        cov.hit(f"order_{order}")
    if drv.stalled["b"]:
        cov.hit("b_stalled")
    if drv.stalled["r"]:
        cov.hit("r_stalled")
    if drv.max_outstanding["w"] >= 2:
        cov.hit("outstanding_w2")
    if drv.max_outstanding["r"] >= 2:
        cov.hit("outstanding_r2")
    drv.b_ready_p = drv.r_ready_p = 1.0
    await check_all_reads(csr, drv)
    await csr.check_outputs()
    cov.check(Path.cwd())  # the run directory


def test_hft_csr():
    run_cocotb(toplevel="hft_csr", filelists=["common.f", "core.f", "csr.f"], test_module="test_hft_csr")
